window.__votdWeek && window.__votdWeek({"week":"2029-09-10","reading":"Doctrine and Covenants 98–101","days":[{"d":"2029-09-10","ref":"D&C 98:2","b":"D&C","c":98,"v":2,"he":"קַוּוֹ לַיהוָה כִּי תְפִלּוֹתֵיכֶם בָּאוּ בְאׇזְנֵי יְהוָה צְבָאוֹת וְנִכְתְּבוּ בַּחוֹתָם וּבָעֵדוּת הַזֹּאת יְהוָה נִשְׁבַּע וְגָזַר אֲשֶׁר־יִנָּתְנוּ׃","en":"Waiting patiently on the Lord, for your prayers have entered into the ears of the Lord of Sabaoth, and are recorded with this seal and testament—the Lord hath sworn and decreed that they shall be granted."},{"d":"2029-09-11","ref":"D&C 98:37","b":"D&C","c":98,"v":37,"he":"וַאֲנִי יְהוָה אֶלָּחֵם מִלְחֲמוֹתֵיהֶם וּמִלְחֲמוֹת בְּנֵיהֶם וּבְנֵי בְנֵיהֶם עַד הִנָּקְמָם מִכׇּל־אֹיְבֵיהֶם עַד הַדּוֹר הַשְּׁלִישִׁי וְהָרְבִיעִי׃","en":"And I, the Lord, would fight their battles, and their children's battles, and their children's children's, until they had avenged themselves on all their enemies, to the third and fourth generation."},{"d":"2029-09-12","ref":"D&C 99:7","b":"D&C","c":99,"v":7,"he":"וְאַחֲרֵי שָׁנִים אֲחָדוֹת אִם תַּחְפֹּץ מִמֶּנִּי תּוּכַל לַעֲלוֹת גַּם אַתָּה אֶל־הָאָרֶץ הַטּוֹבָה לָרֶשֶׁת נַחֲלָתֶךָ׃","en":"And after a few years, if thou desirest of me, thou mayest go up also unto the goodly land, to possess thine inheritance;"},{"d":"2029-09-13","ref":"D&C 100:5","b":"D&C","c":100,"v":5,"he":"לָכֵן אָמֵן אֲנִי אֹמֵר לָכֶם הָרִימוּ קוֹלְכֶם אֶל־הָעָם הַזֶּה דַּבְּרוּ הַמַּחֲשָׁבוֹת אֲשֶׁר אָשִׂים בְּלִבְּכֶם וְלֹא תֵבֹשׁוּ לִפְנֵי אֲנָשִׁים׃","en":"Therefore, verily I say unto you, lift up your voices unto this people; speak the thoughts that I shall put into your hearts, and you shall not be confounded before men;"},{"d":"2029-09-14","ref":"D&C 100:15","b":"D&C","c":100,"v":15,"he":"לָכֵן יִנָּחֵם לְבַבְכֶם כִּי הַכֹּל יֵעָשֶׂה יַחְדָּו לְטוֹבַת הַהוֹלְכִים בְּיֹשֶׁר וּלְקִדּוּשׁ הַכְּנֵסִיָּה׃","en":"Therefore, let your hearts be comforted; for all things shall work together for good to them that walk uprightly, and to the sanctification of the church."},{"d":"2029-09-15","ref":"D&C 101:7","b":"D&C","c":101,"v":7,"he":"קָשׁוּ לִשְׁמֹעַ בְּקוֹל יְהוָה אֱלֹהֵיהֶם לָכֵן יְהוָה אֱלֹהֵיהֶם אָטֵם לִשְׁמֹעַ תְּפִלּוֹתֵיהֶם לַעֲנוֹתָם בְּיוֹם צָרָתָם׃","en":"They were slow to hearken unto the voice of the Lord their God; therefore, the Lord their God is slow to hearken unto their prayers, to answer them in the day of their trouble."},{"d":"2029-09-16","ref":"D&C 101:8","b":"D&C","c":101,"v":8,"he":"בִּימֵי שְׁלוֹמָם הֵקַלּוּ בַּעֲצָתִי אַךְ בְּיוֹם צָרָתָם בְּאֹנֶס יְמַשְּׁשׁוּנִי׃","en":"In the day of their peace they esteemed lightly my counsel; but, in the day of their trouble, of necessity they feel after me."}]});
